{"chunk_id":"bf397d","wall_time_seconds":1.000628564,"session_id":33310,"original_token_count":711,"output":"import { readFileSync } from "node:fs";
import type { AnalysisSource } from "./analysisSource";

export type PlaybackStatus = {
  mode: "current" | "original";
  state: "playing" | "paused" | "finished" | "stopped";
  speed: number;
  sourceFirst: number;
  sourceLast: number;
  now: number;
  loop: boolean;
  cycle: number;
  loopGapSec: number;
};

type PlayerState = {
  schema_version: number;
  mode: PlaybackStatus["mode"];
  state: PlaybackStatus["state"];
  speed: number;
  source_first: number;
  source_last: number;
  current_time: number;
  updated_wall: number;
  loop?: boolean;
  cycle?: number;
  loop_gap?: number;
};

export interface PlaybackSource extends AnalysisSource { status(): PlaybackStatus | null; }

export function createPlaybackSource(stateFile: string, wallNowSec = () => Date.now() / 1000): PlaybackSource {
  const status = (): PlaybackStatus | null => {
    try {
      const state = JSON.parse(readFileSync(stateFile, "utf8")) as PlayerState;
      if (state.schema_version !== 1 || !["current", "original"].includes(state.mode) ||
        !["playing", "paused", "finished", "stopped"].includes(state.state) ||
        !Number.isFinite(state.speed) || state.speed <= 0 || !Number.isFinite(state.current_time) ||
        !Number.isFinite(state.updated_wall) ||
        (state.loop !== undefined && typeof state.loop !== "boolean") ||
        (state.cycle !== undefined && (!Number.isSafeInteger(state.cycle) || state.cycle < 0)) ||
        (state.loop_gap !== undefined && (!Number.isFinite(state.loop_gap) || state.loop_gap <= 0))) return null;
      const elapsed = Math.max(0, wallNowSec() - state.updated_wall);
      const now = state.state === "playing"
        ? state.mode === "original" ? Math.min(state.source_last, state.current_time + elapsed * state.speed) : state.current_time + elapsed
        : state.current_time;
      return { mode: state.mode, state: state.state, speed: state.speed,
        sourceFirst: state.source_first, sourceLast: state.source_last, now,
        loop: state.loop ?? false, cycle: state.cycle ?? 0, loopGapSec: state.loop_gap ?? 1 };
    } catch { return null; }
  };
  return {
    nowSec() { const current = status(); return current?.mode === "original" ? current.now : wallNowSec(); },
    runtimeMutationError: "settings and process operations are disabled during playback",
    registerRoutes(app) {
      app.get("/api/playback", async (_request, reply) => {
        const current = status();
        return current ? { enabled: true, ...current } : reply.code(503).send({ error: "player state is unavailable" });
      });
    },
    statusMessages() {
      const current = status();
      return current ? [{ type: "playback:status", playback: { enabled: true, ...current } }] : [];
    },
    status
  };
}

