function timelineBounds(rows: TimelineRow[]) {
  if (rows.length === 0) {
    const now = dataNowSec();
    return { from: now - 300, to: now };
  }

  let from = Number.POSITIVE_INFINITY;
  let to = Number.NEGATIVE_INFINITY;
  for (const row of rows) {
    from = Math.min(from, row.firstSeen, ...row.segments.map((segment) => segment.start));
    to = Math.max(to, row.lastSeen, ...row.segments.map((segment) => segment.end ?? row.lastSeen));
  }

  if (!Number.isFinite(from) || !Number.isFinite(to) || to <= from) {
    const now = dataNowSec();
    return { from: now - 300, to: now };
  }

  return { from, to };
}


